package cn.zhuatech.iam.deep;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="iam_tenants",uniqueConstraints=@UniqueConstraint(columnNames="tenantCode"))class IamTenant{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=40)String tenantCode;@Column(nullable=false,length=120)String name;@Column(nullable=false,length=20)String status="DRAFT";LocalDateTime createdAt;protected IamTenant(){}IamTenant(String c,String n){tenantCode=c;name=n;createdAt=LocalDateTime.now();}}
@Entity @Table(name="iam_identities",uniqueConstraints=@UniqueConstraint(columnNames={"tenantId","username"}))class IamIdentity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Version long version;@Column(nullable=false)Long tenantId;@Column(nullable=false,length=60)String username;@Column(nullable=false,length=120)String displayName;@Column(nullable=false,length=120)String department;boolean mfaEnabled;@Column(nullable=false,length=20)String status="ACTIVE";LocalDateTime createdAt;protected IamIdentity(){}IamIdentity(Long t,String u,String n,String d,boolean m){tenantId=t;username=u;displayName=n;department=d;mfaEnabled=m;createdAt=LocalDateTime.now();}}
@Entity @Table(name="iam_role_definitions",uniqueConstraints=@UniqueConstraint(columnNames={"tenantId","roleCode"}))class IamRoleDefinition{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false)Long tenantId;@Column(nullable=false,length=50)String roleCode;@Column(nullable=false,length=120)String name;@Column(nullable=false,length=1000)String permissions;boolean privileged;@Column(nullable=false,length=20)String status="ACTIVE";protected IamRoleDefinition(){}IamRoleDefinition(Long t,String c,String n,String p,boolean x){tenantId=t;roleCode=c;name=n;permissions=p;privileged=x;}}
@Entity @Table(name="iam_access_requests",uniqueConstraints=@UniqueConstraint(columnNames="requestNo"))class IamAccessRequest{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Version long version;@Column(nullable=false,length=50)String requestNo;@Column(nullable=false)Long identityId;@Column(nullable=false)Long roleId;@Column(nullable=false,length=300)String reason;LocalDate validUntil;@Column(nullable=false,length=25)String status="PENDING_APPROVAL";@Column(length=300)String reviewNote;LocalDateTime createdAt;protected IamAccessRequest(){}IamAccessRequest(String n,Long i,Long r,String reason,LocalDate until){requestNo=n;identityId=i;roleId=r;this.reason=reason;validUntil=until;createdAt=LocalDateTime.now();}}
@Entity @Table(name="iam_access_assignments",uniqueConstraints=@UniqueConstraint(columnNames={"identityId","roleId"}))class IamAccessAssignment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false)Long identityId;@Column(nullable=false)Long roleId;@Column(nullable=false,length=20)String status="ACTIVE";LocalDate validUntil;LocalDateTime grantedAt;LocalDateTime revokedAt;protected IamAccessAssignment(){}IamAccessAssignment(Long i,Long r,LocalDate u){identityId=i;roleId=r;validUntil=u;grantedAt=LocalDateTime.now();}}
@Entity @Table(name="iam_domain_audit")class IamDomainAudit{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;String action;String businessNo;String detailText;LocalDateTime occurredAt;protected IamDomainAudit(){}IamDomainAudit(String a,String n,String d){action=a;businessNo=n;detailText=d;occurredAt=LocalDateTime.now();}}
